('241.为运算表达式设计优先级',2,1000,128,'给你一个由数字和运算符组成的字符串 expression，按不同优先级组合数字和运算符，计算并返回所有可能组合的结果。','输入:expression = "2-1-1" 输出:[0,2]','class Solution {public List<Integer> diffWaysToCompute(String expression) {}}','public static void main(String[] args) {Solution s=new Solution();System.out.println(s.diffWaysToCompute("2-1-1"));}',1,'2026-09-28 10:00:00',null,null),
('242.有效的字母异位词',1,1000,128,'给定两个字符串 s 和 t，判断 t 是否是 s 的字母异位词，即两个字符串中字母出现的次数相同。','输入:s = "anagram", t = "nagaram" 输出:true','class Solution {public boolean isAnagram(String s, String t) {}}','public static void main(String[] args) {Solution s=new Solution();System.out.println(s.isAnagram("anagram","nagaram"));}',1,'2026-09-28 10:00:00',null,null),
('243.最短单词距离',1,1000,128,'给定一个字符串数组 wordsDict 和两个不同的单词 word1、word2，返回列表中这两个单词之间的最短距离。','输入:wordsDict = ["practice","makes","perfect","coding","makes"], word1 = "coding", word2 = "practice" 输出:3','class Solution {public int shortestDistance(String[] wordsDict, String word1, String word2) {}}','public static void main(String[] args) {Solution s=new Solution();System.out.println(s.shortestDistance(new String[]{"practice","makes","perfect","coding","makes"},"coding","practice"));}',1,'2026-09-28 10:00:00',null,null),
('244.最短单词距离 II',2,1000,128,'设计一个数据结构，构造函数接收单词数组，提供方法 shortest 返回两个单词在数组中的最短距离，该方法会被多次调用。','输入:["WordDistance","shortest","shortest"] 输出:[null,3,1]','class WordDistance{public WordDistance(String[] wordsDict){}public int shortest(String word1, String word2){return 0;}}','public static void main(String[] args) {WordDistance wd=new WordDistance(new String[]{"practice","makes","perfect","coding","makes"});}',1,'2026-09-28 10:00:00',null,null),
('245.最短单词距离 III',2,1000,128,'给定单词数组 wordsDict 和两个单词 word1、word2，两单词可能相同，返回两个单词在列表中的最短距离。','输入:wordsDict = ["practice","makes","perfect","coding","makes"], word1 = "makes", word2 = "makes" 输出:3','class Solution {public int shortestWordDistance(String[] wordsDict, String word1, String word2) {}}','public static void main(String[] args) {Solution s=new Solution();System.out.println(s.shortestWordDistance(new String[]{"practice","makes","perfect","coding","makes"},"makes","makes"));}',1,'2026-09-28 10:00:00',null,null),
('246.中心对称数',1,1000,128,'中心对称数是指一个数字旋转 180 度之后看起来依然相同的数字。给定一个字符串 num，判断它是否是中心对称数。','输入:num = "69" 输出:true','class Solution {public boolean isStrobogrammatic(String num) {}}','public static void main(String[] args) {Solution s=new Solution();System.out.println(s.isStrobogrammatic("69"));}',1,'2026-09-28 10:00:00',null,null),
