('417.太平洋大西洋水流问题',2,1000,128,'给定一个 m x n 的岛屿高度矩阵，返回水能同时流向太平洋和大西洋的单元格坐标列表。','输入:heights = [[1,2,2,3,5],[3,2,3,4,4],[2,4,5,3,1],[6,7,1,4,5],[5,1,1,2,4]] 输出:[[0,4],[1,3],[1,4],[2,2],[3,0],[3,1],[4,0]]','class Solution {public List<List<Integer>> pacificAtlantic(int[][] heights) {}}','public static void main(String[] args) {Solution s=new Solution();}',1,'2026-09-28 10:00:00',null,null),
('418.屏幕可显示句子的数量',2,1000,128,'给定一个句子数组和 rows x cols 的屏幕，句子循环填充屏幕，返回能在屏幕上完整显示的句子总次数。','输入:sentence = ["hello","world"], rows = 2, cols = 8 输出:1','class Solution {public int wordsTyping(String[] sentence, int rows, int cols) {}}','public static void main(String[] args) {Solution s=new Solution();System.out.println(s.wordsTyping(new String[]{"hello","world"},2,8));}',1,'2026-09-28 10:00:00',null,null),
('419.甲板上的战舰',2,1000,128,'给定一个二维甲板，X 表示战舰，战舰只能水平或垂直放置且互不相邻，计算战舰的数量。','输入:board = [["X",".",".","X"],[".",".",".","X"],[".",".",".","X"]] 输出:2','class Solution {public int countBattleships(char[][] board) {}}','public static void main(String[] args) {Solution s=new Solution();}',1,'2026-09-28 10:00:00',null,null),
('420.强密码检验器',3,1000,128,'给定一个密码字符串，返回将其修改为强密码所需的最少操作次数，强密码需满足长度、大小写和数字的要求。','输入:password = "a" 输出:5','class Solution {public int strongPasswordChecker(String password) {}}','public static void main(String[] args) {Solution s=new Solution();System.out.println(s.strongPasswordChecker("a"));}',1,'2026-09-28 10:00:00',null,null),
('421.数组中两个数的最大异或值',2,1000,128,'给你一个整数数组 nums，返回 nums[i] XOR nums[j] 的最大运算结果。','输入:nums = [3,10,5,25,2,8] 输出:28','class Solution {public int findMaximumXOR(int[] nums) {}}','public static void main(String[] args) {Solution s=new Solution();System.out.println(s.findMaximumXOR(new int[]{3,10,5,25,2,8}));}',1,'2026-09-28 10:00:00',null,null),
('422.有效的单词方块',1,1000,128,'给定一组单词列表，判断这些单词是否构成一个有效的单词方块，即第 i 行和第 i 列的字符串相同。','输入:words = ["abcd","bnrt","crmy","dtye"] 输出:true','class Solution {public boolean validWordSquare(List<String> words) {}}','public static void main(String[] args) {Solution s=new Solution();}',1,'2026-09-28 10:00:00',null,null),
('423.从英文中重建数字',2,1000,128,'给定一个乱序的英文数字字符串 s，重建并返回按升序排列的数字。','输入:s = "owoztneoer" 输出:"012"','class Solution {public String originalDigits(String s) {}}','public static void main(String[] args) {Solution s=new Solution();System.out.println(s.originalDigits("owoztneoer"));}',1,'2026-09-28 10:00:00',null,null),
('424.替换后的最长重复字符',2,1000,128,'给你一个字符串 s 和一个整数 k，最多替换 k 个字符，返回替换后包含相同字母的最长子串长度。','输入:s = "ABAB", k = 2 输出:4','class Solution {public int characterReplacement(String s, int k) {}}','public static void main(String[] args) {Solution s=new Solution();System.out.println(s.characterReplacement("ABAB",2));}',1,'2026-09-28 10:00:00',null,null);
INSERT INTO tb_question (title, difficulty, time_limit, space_limit, content, question_case, default_code, main_fuc, create_by, create_time, update_by, update_time) VALUES
('425.单词方块',3,1000,128,'给定一组互不相同的单词，返回所有能组成单词方块的组合，单词方块每行每列的单词都相同。','输入:words = ["area","lead","wall","lady","ball"] 输出:[["ball","area","lead","lady"],["wall","area","lead","lady"]]','class Solution {public List<List<String>> wordSquares(String[] words) {}}','public static void main(String[] args) {Solution s=new Solution();}',1,'2026-09-28 10:00:00',null,null),
('426.将二叉搜索树转化为排序的双向链表',2,1000,128,'将一个二叉搜索树原地转换为一个排序的循环双向链表，返回最小元素节点的指针。','输入:root = [4,2,5,1,3] 输出循环双向链表','class Node{int val;Node left;Node right;Node(){}Node(int v){val=v;}}class Solution {public Node treeToDoublyList(Node root) {}}','public static void main(String[] args) {Solution s=new Solution();}',1,'2026-09-28 10:00:00',null,null),
('427.建立四叉树',2,1000,128,'给定一个 n x n 的 01 矩阵，构建一棵四叉树表示该矩阵，返回根节点。','输入:grid = [[0,1],[1,0]] 输出四叉树根','class Node{public boolean val;public boolean isLeaf;public Node topLeft;public Node topRight;public Node bottomLeft;public Node bottomRight;Node(){}Node(boolean v,boolean l){val=v;isLeaf=l;}}class Solution {public Node construct(int[][] grid) {}}','public static void main(String[] args) {Solution s=new Solution();}',1,'2026-09-28 10:00:00',null,null),
('428.序列化和反序列化 N 叉树',3,1000,128,'设计算法实现 N 叉树的序列化与反序列化，将树转为字符串并能还原。','输入:root = [1,null,3,2,4,null,5,6] 输出还原相同N叉树','class Node{int val;List<Node> children;Node(){}Node(int v){val=v;}}class Codec{public String serialize(Node root){return "";}public Node deserialize(String data){return null;}}','public static void main(String[] args) {Codec c=new Codec();}',1,'2026-09-28 10:00:00',null,null),
('429.N 叉树的层序遍历',2,1000,128,'给定一棵 N 叉树的根节点，返回其节点值的层序遍历，每层一组。','输入:root = [1,null,3,2,4,null,5,6] 输出:[[1],[3,2,4],[5,6]]','class Node{int val;List<Node> children;Node(){}Node(int v){val=v;}}class Solution {public List<List<Integer>> levelOrder(Node root) {}}','public static void main(String[] args) {Solution s=new Solution();}',1,'2026-09-28 10:00:00',null,null),
('430.扁平化多级双向链表',2,1000,128,'给定一个多级双向链表，将链表扁平化，使所有节点都出现在同一级，返回扁平化后的头节点。','输入:head = [1,2,3,4,5,6,null,null,null,7,8,9,10,null,null,11,12] 输出:[1,2,3,7,8,11,12,9,10,4,5,6]','class Node{int val;Node prev;Node next;Node child;Node(){}Node(int v){val=v;}}class Solution {public Node flatten(Node head) {}}','public static void main(String[] args) {Solution s=new Solution();}',1,'2026-09-28 10:00:00',null,null),
('431.将 N 叉树编码为二叉树',3,1000,128,'设计算法将一棵 N 叉树编码为一棵二叉树，并能将二叉树解码还原为原 N 叉树。','输入:root = [1,null,3,2,4,null,5,6] 输出编码解码后还原','class Node{int val;List<Node> children;Node(){}Node(int v){val=v;}}class TreeNode{int val;TreeNode left;TreeNode right;TreeNode(){}TreeNode(int v){val=v;}}class Codec{public TreeNode encode(Node root){return null;}public Node decode(TreeNode root){return null;}}','public static void main(String[] args) {Codec c=new Codec();}',1,'2026-09-28 10:00:00',null,null),
